 = container.gameObject.GetComponent<RefreshHandler>(); if (obj) obj.Reset(); else container.gameObject.AddComponent<RefreshHandler>(); } if (debugLogEnabled) LogToFile("PopulateContainer", $"{DateTime.Now.ToString()} - SUCCESS > spawned '{container.inventory.capacity}' items in '{container}' > {ContentsStringHash(container.inventory)}", this); return true; }  string ContentsStringHash(ItemContainer itemCont) { string text = string.Empty; for (int i = 0; i < itemCont.capacity; i++) { global::Item slot = itemCont.GetSlot(i); if (slot != null) { text += slot.info.shortname; text += $"_x{slot.amount} "; } } return text; }  void OnTerrainInitialized() { if (debugLogEnabled) LogToFile("PopulateContainer", $"{DateTime.Now.ToString()} - SERVERSTARTUP > fresh server startup detected", this); }  void PopulateHeliCrate(LootContainer container) { if (container == null) return; int index; index = rngHeli.Next(heliData.Count); if (rngHeliList.Contains(index)) { NextFrame(()=>{ if (container) PopulateHeliCrate(container); }); return; } rngHeliList.Add(index); var lootContent = heliData.ToArray()[index] as Dictionary<string, object>; int itemCount = lootContent.Count; if (itemCount == 0) return; Dictionary<string, object> con; object containerobj; if (lootContainers.TryGetValue(container.ShortPrefabName, out containerobj)) { con = containerobj as Dictionary<string, object>; if (!(bool)con["Enabled"]) return; } else return; if (container.inventory == null) { container.inventory = new ItemContainer(); container.inventory.ServerInitialize(null, container.inventorySlots); container.inventory.GiveUID(); } else ClearContainer(container); container.inventory.capacity = itemCount; container.inventorySlots = itemCount; int divider = 1; if (con.ContainsKey("MinAmountDivider")) divider = (int)con["MinAmountDivider"]; if (divider < 1) divider = 1; foreach (var loot in lootContent) { Item item; object limits; bool DropSkinned = false; var itemDef = ItemManager.FindItemDefinition(loot.Key); if 