t * multiplier; if (amount.itemDef.isWearable || itemMultiplierExcludes.Contains(amount.itemDef.shortname) || (amount.itemDef.condition.enabled && amount.itemDef.GetComponent<ItemModDeployable>() == null)) options = (int)amount.amount; } else { object limits; if (lootCategoryLimits.TryGetValue(amount.itemDef.category.ToString(), out limits)) { if ((int)(limits as Dictionary<string, object>)["VanillaMultiplier"] > 1) options = (int)amount.amount * (int)(limits as Dictionary<string, object>)["VanillaMultiplier"]; else options = (int)amount.amount; if (amount.itemDef.isWearable || itemMultiplierExcludes.Contains(amount.itemDef.shortname) || (amount.itemDef.condition.enabled && amount.itemDef.GetComponent<ItemModDeployable>() == null)) options = (int)amount.amount; } else options = (int)amount.amount; } if (!fancyDropLootSpawn.ContainsKey(amount.itemDef.shortname)) fancyDropLootSpawn.Add(amount.itemDef.shortname, options); } } }  void GetHeliLoot(bool recreate = false) { if (!enableHeliLoadOut) return; heliLoot = getFile("HeliLoot"); heliData = new List<object>(); heliData = heliLoot["LoadOut"] as List<object>; if (recreate || heliData == null) heliData = new List<object>(); if (recreate || heliData.Count == 0) { var loot = GameManager.server.CreateEntity("assets/prefabs/npc/patrol helicopter/heli_crate.prefab", new Vector3(), new Quaternion(), false).GetComponent<LootContainer>(); string name = loot.GetComponent<BaseEntity>().ShortPrefabName; if (lootContainers.ContainsKey(name)) GetHeliLootSpawn(loot.lootDefinition, name, (bool)(lootContainers[name] as Dictionary<string, object>)["UseVanilla"], (int)(lootContainers[name] as Dictionary<string, object>)["UsedMultiplier"]); else GetHeliLootSpawn(loot.lootDefinition, name); heliLoot.Set("LoadOut", heliData); heliLoot.Save(); loot.Kill(); } }  void GetHeliLootSpawn(LootSpawn lootSpawn, string main, bool mainvanilla = false, int mainmultipy = 1) { if (lootSpawn.subSpawn != null && lootSpawn.subSpawn.Length > 0) { foreach (var entry in lootSpawn.subSpawn) GetHeliLootSpawn(entry.category, main, mainvanilla, mainmultipy); return; } if (lootSpawn.items != null && lootSpawn.items.Length > 0) { var content = new Dictionary<string, int>(); foreach (var amount in lootSpawn.items) { if (amount.itemDef.shortname == "wood") continue; int options = 0; if (mainvanilla) { int multiplier = mainmultipy; if (multiplier <= 1) multiplier = 1; options = (int)amount.amount * multiplier; if (amount.itemDef.isWearable || itemMultiplierExcludes.Contains(amount.itemDef.shortname) || (amount.itemDef.condition.enabled && amount.itemDef.GetComponent<ItemModDeployable>() == null)) options = (int)amount.amount; } else { object limits; if (lootCategoryLimits.TryGetValue(amount.itemDef.category.ToString(), out limits)) { if ((int)(limits as Dictionary<string, object>)["VanillaMultiplier"] > 1) options = (int)amount.amount * (int)(limits as Dictionary<string, object>)["VanillaMultiplier"]; else options = (int)amount.amount; if (amount.itemDef.isWearable || itemMultiplierExcludes.Contains(amount.itemDef.shortname) || (amount.itemDef.condition.enabled && amount.itemDef.GetComponent<ItemModDeployable>() == null)) options = (int)amount.amount; } else options = (int)amount.amount; } content.Add(amount.itemDef.shortname, options); } heliData.Add(content); } }  void LoadItemRaritys(bool doLog = true) { bool changed = false; rarityOverrides = null; itemRaritys = getFile("ItemRaritys"); if (itemRaritys["ItemRaritys"] == null) { var items = new Dictionary<string, object>(); var internaloverride = rarityOverrideList(); foreach (var item in ItemManager.GetItemDefinitions()) { object itemoverride; if (enableDefaultRarityOverrides && internaloverride.TryGetValue(item.shortname, out itemoverride)) items.Add(item.shortname, (int)itemoverride); else items.Add(item.shortname, item.rarity); } itemRaritys.Set("ItemRaritys", items); itemRaritys.Save(); } else { foreach (var item in (itemRaritys["ItemRaritys"] as Dictionary<string, object>).ToList()) { if (ItemManager.FindItemDefinition(item.Key) == null) { (itemRaritys["ItemRaritys"] as Dictionary<string, object>).Remove(item.Key); changed = true; } else { if ((int)item.Value < 0) ItemManager.FindItemDefinition(item.Key).rarity = Rarity.None; else if ((int)item.Value > 4) ItemManager.FindItemDefinition(item.Key).rarity = Rarity.VeryRare; else ItemManager.FindItemDefinition(item.Key).rarity = (Rarity)item.Value; } } foreach (var item in ItemManager.GetItemDefinitions()) { if (!(itemRaritys["ItemRaritys"] as Dictionary<string, object>).ContainsKey(item.shortname)) { var internaloverride = rarityOverrideList(); object itemoverride; if (internaloverride.TryGetValue(item.shortname, out itemoverride)) (itemRaritys["ItemRaritys"] as Dictionary<string, object>).Add(item.shortname, (int)itemoverride); else (itemRaritys["ItemRaritys"] as Dictionary<string, object>).Add(item.shortname, item.rarity); changed = true; } } if (changed) itemRaritys.Save(); } rarityOverrides = itemRaritys["ItemRaritys"] as Dictionary<string, object>; itemRaritys.Clear(); }  void LoadWeaponsAmmo() { weaponAmmoPreload = (Dictionary<string, object>)Config["Weapons", "Ammo"]; if (weaponAmmoPreload != null && weaponAmmoPreload.Count() > 0) { var chkweapons = ItemManager.GetItemDefinitions().Where(p => p.category == ItemCategory.Weapon); foreach (var weapon in chkweapons) { if (!guidToPathCopy.ContainsKey(weapon.GetComponent<ItemModEntity>().entityPrefab.guid)) continue; if (weaponAmmoPreload.ContainsKey(weapon.shortname)) continue; var item = ItemManager.Create(weapon); if (item.GetHeldEntity() is BaseProjectile) weaponAmmoPreload.Add(weapon.shortname, weapon.GetComponent<ItemModEntity>().entityPrefab.Get().GetComponent<BaseProjectile>().primaryMagazine.contents); item.Remove(0f); } Config["Weapons", "Ammo"] = weaponAmmoPreload; Config.Save(); return; } else { weaponAmmoPreload = new Dictionary<string, object>(); var weapons = ItemManager.GetItemDefinitions().Where(p => p.category == ItemCategory.Weapon); foreach (var weapon in weapons) { if (!guidToPathCopy.ContainsKey(weapon.GetComponent<ItemModEntity>().entityPrefab.guid)) continue; var item = ItemManager.CreateByName(weapon.shortname); if (item.GetHeldEntity() is BaseProjectile) weaponAmmoPreload.Add(weapon.shortname, weapon.GetComponent<ItemModEntity>().entityPrefab.Get().GetComponent<BaseProjectile>().primaryMagazine.contents); item.Remove(0f); } Config["Weapons", "Ammo"] = weaponAmmoPreload; Config.Save(); } }  void LoadAllContainers() { var allTypes = Resources.FindObjectsOfTypeAll<LootContainer>().Where(c => !c.isActiveAndEnabled).ToList(); foreach (var loot in allTypes) { if (!AllContainerTypes.ContainsKey(loot.ShortPrefabName)) AllContainerTypes[loot.ShortPrefabName] = loot.PrefabName; if (!AllLootSpawns.ContainsKey(loot.ShortPrefabName)) AllLootSpawns[loot.ShortPrefabName] = loot.lootDefinition; } foreach (var lootprefab in lootPrefabs) { var loot = GameManager.server.CreateEntity(lootprefab, new Vector3(), new Quaternion(), false).GetComponent<LootContainer>(); if (!AllContainerTypes.ContainsKey(loot.ShortPrefabName)) AllContainerTypes[loot.ShortPrefabName] = loot.PrefabName; if (!AllLootSpawns.ContainsKey(loot.ShortPrefabName)) AllLootSpawns[loot.ShortPrefabName] = loot.lootDefinition; loot.KillMessage(); } }  [ConsoleCommand("al.reload")] void consoleReload(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; manualReload = true; LoadConfig(); LoadVariables(); NextFrame(()=>ServerMgr.Instance.StartCoroutine(UpdateInternals(true))); }  [ConsoleCommand("al.refreshboxes")] void consoleRefresh(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; if (!pluginEnabled) { SendReply(arg, "Plugin is disabled by config"); return; } int populatedContainers = 0; timer.Once(0f, () => { foreach (var container in UnityEngine.Object.FindObjectsOfType<LootContainer>()) { if (PopulateContainer(container)) populatedContainers++; } SendReply(arg, $"Refreshed '{populatedContainers}' LootContainer"); }); }  [ConsoleCommand("al.rarityreload")] void consoleRarityReload(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; LoadItemRaritys(); SendReply(arg, $"Reloaded '{rarityOverrides.Count}' raritys"); SendReply(arg, $"New raritys will be active in the loot tables after running reload/lootreload or serverrestart"); }  [ConsoleCommand("al.rarityset")] void consoleRaritySet(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; if (arg.Args == null || arg.Args.Length <= 1 || arg.Args.Length > 2) { SendReply(arg, "Example: al.rarityset <name> <x|rarity-num> "); return; } ItemDefinition def = null; if (arg.Args != null && arg.Args.Length > 1) { def = ItemManager.FindItemDefinition(arg.Args[0]); if (def == null) { SendReply(arg, $"Item \"{arg.Args[0]}\" not found"); return; } int num = -1; if (arg.Args.Length > 1) if (!int.TryParse(arg.Args[1], out num)) { SendReply(arg, $"Set a full number for the rarity (0..4)"); return; } def.rarity = (Rarity)num; if (rarityOverrides.ContainsKey(arg.Args[0])) rarityOverrides[arg.Args[0]] = num; else rarityOverrides.Add(arg.Args[0], num); itemRaritys = getFile("ItemRaritys"); itemRaritys.Set("ItemRaritys", rarityOverrides); itemRaritys.Save(); itemRaritys.Clear(); SendReply(arg, $"The new rarity will be active after running reload/lootreload or serverrestart"); } }  [ConsoleCommand("al.lootreload")] void consoleLootReload(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; if (arg.Args == null || arg.Args.Length != 1 || arg.Args[0] != "reset") { SendReply(arg, "Usage: lootreload reset | Recreates loottables with your category and container settings"); return; } pluginEnabled = false; lootTable = getFile("LootTables"); var lootcont = lootTable.Get("LootContainer"); lootTable.Clear(); lootTable.Set("LootContainer", lootcont); lootTable.Save(); LoadConfig(); LoadVariables(); pluginEnabled = false; Config["Generic", "pluginEnabled"] = false; Config.Save(); NextFrame(()=> { ServerMgr.Instance.StartCoroutine(UpdateInternals(true, true)); SendReply(arg, $"LootData successfully recreated!"); }); }  [ConsoleCommand("al.lootmultiplier")] void consoleLootMultiplier(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; if (arg.Args == null || arg.Args.Length < 1 ) { SendReply(arg, "Usage: lootmultiplier <number> | Recreates loottables with all containers using vanilla multiplier"); return; } int num = -1; int.TryParse(arg.Args[0], out num); if (num < 1) { SendReply(arg, "The Limit must be a full number and greater then zero"); return; } pluginEnabled = false; lootTable = getFile("LootTables"); var lootcont = lootTable.Get("LootContainer") as Dictionary <string,object>; NextFrame(()=> { foreach (var cont in lootcont) { (lootcont[cont.Key] as Dictionary <string,object>)["UseVanilla"] = true; (lootcont[cont.Key] as Dictionary <string,object>)["UsedMultiplier"] = num; foreach (var lootprefab in lootPrefabs) { if (lootprefab.Contains(cont.Key.ToString()+".prefab")) { var loot = GameManager.server.CreateEntity(lootprefab, new Vector3(), new Quaternion(), false).GetComponent<LootContainer>(); (lootcont[cont.Key] as Dictionary<string, object>)["ScrapAmount"] = loot.scrapAmount * num; loot.KillMessage(); } } } lootTable.Clear(); lootTable.Set("LootContainer", lootcont); lootTable.Save(); LoadConfig(); LoadVariables(); NextFrame(()=> { ServerMgr.Instance.StartCoroutine(UpdateInternals(true, false)); SendReply(arg, $"LootData with UsedMultiplier '{num}' successfully recreated"); }); }); }  [ConsoleCommand("al.enable")] void consoleEnable(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; if (pluginEnabled && (bool)Config["Generic", "pluginEnabled"]) { if (firstSetup) { firstSetup = false; NextFrame(() => { ServerMgr.Instance.StartCoroutine(UpdateInternals(true)); SendReply(arg, "Plugin is now active and running"); }); return; } SendReply(arg, "Plugin already active and running"); firstSetup = false; Changed = false; return; } LoadConfig(); LoadVariables(); Config["Generic", "pluginEnabled"] = true; pluginEnabled = true; SaveConfig(); firstSetup = false; NextFrame(() => { ServerMgr.Instance.StartCoroutine(UpdateInternals(true)); SendReply(arg, "Plugin is now active and running"); }); }  [ConsoleCommand("al.disable")] void consoleDisable(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; if (!pluginEnabled && !(bool)Config["Generic", "pluginEnabled"]) { SendReply(arg, "Plugin already disabled"); return; } LoadConfig(); LoadVariables(); Config["Generic", "pluginEnabled"] = false; pluginEnabled = false; SaveConfig(); SendReply(arg, "Plugin is now disabled"); }  [ConsoleCommand("al.itemlimit")] void consoleItemLimit(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; if (arg.Args == null || arg.Args.Length != 2) { SendReply(arg, "Usage: itemlimit shortname x"); return; } if (ItemManager.FindItemDefinition(arg.Args[0]) == null) { SendReply(arg, $"Item name '{arg.Args[0]}' not found in game"); return; } var name = arg.Args[0]; int num = 0; int.TryParse(arg.Args[1], out num); if (num == 0) { SendReply(arg, "The Limit must be a full number and greater then zero"); return; } int modified = 0; foreach (var data in lootData) { foreach (var limit in (data.Value as Dictionary<string, object>).ToList()) { if (name == limit.Key.ToString() && (int)limit.Value != num) { (lootData[data.Key] as Dictionary<string, object>)[limit.Key] = num; modified++; } } } if (modified > 0) { SendReply(arg, $"Changed '{modified}' entries for item '{name}' by the new number '{num}'"); SendReply(arg, $"New settings will be active in the loot tables after running reload/lootreload or serverrestart"); lootTable = getFile("LootTables"); lootTable.Set("LootData", lootData); lootTable.Save(); lootTable.Clear(); } else SendReply(arg, $"No entries for item '{name}' found"); }  [ConsoleCommand("al.itemremove")] void consoleItemRemove(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; if (arg.Args == null || arg.Args.Length != 1) { SendReply(arg, "Usage: itemremove shortname"); return; } if (ItemManager.FindItemDefinition(arg.Args[0]) == null) { SendReply(arg, $"Item name '{arg.Args[0]}' not found in game"); return; } var name = arg.Args[0]; int modified = 0; foreach (var data in lootData) { foreach (var limit in (data.Value as Dictionary<string, object>).ToList()) { if (name == limit.Key.ToString()) { (lootData[data.Key] as Dictionary<string, object>).Remove(limit.Key); modified++; } } } if (modified > 0) { SendReply(arg, $"Removed '{modified}'entries for item: '{name}'"); SendReply(arg, $"New settings will be active in the loot tables after running reload/lootreload or serverrestart"); lootTable = getFile("LootTables"); lootTable.Set("LootData", lootData); lootTable.Save(); lootTable.Clear(); } else SendReply(arg, $"No entries for item '{name}' found"); }  [ConsoleCommand("al.searchitems")] void consoleSearchItems(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; if (arg.Args == null || arg.Args.Length != 1) { SendReply(arg, "Usage: searchitems <partial name|itemid>"); return; } string searchFor = arg.Args[0].ToLower(); int count = 0; TextTable textTable = new TextTable(); textTable.AddColumn("Shortname"); textTable.AddColumn("Displayname"); textTable.AddColumn("ItemId"); foreach (var itemDef in ItemManager.GetItemDefinitions()) { if (itemDef.shortname.Contains(searchFor) || itemDef.displayName.english.ToLower().Contains(searchFor) || itemDef.itemid.ToString().Contains(searchFor)) { count++; textTable.AddRow(new string[] { itemDef.shortname, itemDef.displayName.english, itemDef.itemid.ToString() }); } if ( count > 15 ) break; } string result = ""; if (count > 15) result = $"\nSearchresult for '{searchFor}' returned more then 15 hits:"; else result = $"\nSearchresult for '{searchFor}':"; SendReply(arg, result + "\n"+textTable.ToString()); }  [ConsoleCommand("al.itemfind")] void consoleItemFind(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; if (arg.Args == null || arg.Args.Length != 1) { SendReply(arg, "Usage: itemfind shortname"); return; } if (ItemManager.FindItemDefinition(arg.Args[0]) == null) { SendReply(arg, $"Item name '{arg.Args[0]}' not found in game"); return; } var name = arg.Args[0]; int found = 0; SendReply(arg, $"Searching limits for item '{name}':"); foreach (var data in lootData) foreach (var limit in (data.Value as Dictionary<string, object>).ToList()) if (name == limit.Key.ToString()) { SendReply(arg, $"LootContainer '{data.Key.ToString()}': '{limit.Value.ToString()}'"); found++; } if (found == 0) SendReply(arg, $"No entries found"); }  [ConsoleCommand("al.itemadd")] void consoleItemAdd(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; if (arg.Args == null || arg.Args.Length < 3) { SendReply(arg, "Usage: itemadd <shortname> x <containername> (container container ...)"); SendReply(arg, "Example: itemadd wood 100 crate_normal crate_normal_2"); return; } if (ItemManager.FindItemDefinition(arg.Args[0]) == null) { SendReply(arg, $"Item name '{arg.Args[0]}' not found in game"); return; } var name = arg.Args[0]; int num = 0; int.TryParse(arg.Args[1], out num); if (num == 0) { SendReply(arg, "The Limit must be a full number and greater then zero"); return; } bool modified = false; for (int i = 2; i < arg.Args.Length; i++) { object data; if (lootData.TryGetValue(arg.Args[i], out data)) { var limits = data as Dictionary<string, object>; object limit; if (limits.TryGetValue(name, out limit)) { SendReply(arg, $"Modified container '{arg.Args[i]}' from '{(int)limit}' to '{num}'"); (lootData[arg.Args[i].ToString()] as Dictionary<string, object>)[name] = num; modified = true; } else { SendReply(arg, $"Added item to container '{arg.Args[i]}'"); (lootData[arg.Args[i].ToString()] as Dictionary<string, object>).Add(name, num); modified = true; } } else SendReply(arg, $"Skipped not existing container '{arg.Args[i]}'"); } if (modified) { SendReply(arg, $"New settings will be active in the loot tables after running reload/lootreload or serverrestart"); lootTable = getFile("LootTables"); lootTable.Set("LootData", lootData); lootTable.Save(); lootTable.Clear(); } else SendReply(arg, $"No entries added or modified"); }  [ConsoleCommand("al.categorylist")] void consoleCategoryList(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; TextTable textTable = new TextTable(); textTable.AddColumn("Category"); textTable.AddColumn("VanillaMultiplier"); textTable.AddColumn("DropSkinned"); foreach (var category in lootCategoryLimits) { var setting = lootCategoryLimits[category.Key] as Dictionary<string, object>; textTable.AddRow(new string[] { category.Key.ToString(), Convert.ToString(setting["VanillaMultiplier"]), (Convert.ToBoolean(setting["DropSkinned"]) ? "Yes" : "No") }); } SendReply(arg, "\n" + textTable.ToString()); }  [ConsoleCommand("al.containertypes")] void consoleContainerTypes(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; TextTable textTable = new TextTable(); textTable.AddColumn("Type"); textTable.AddColumn("Items"); textTable.AddColumn("Enabled"); textTable.AddColumn("UseVanilla"); textTable.AddColumn("UsedMultiplier"); textTable.AddColumn("MinAmountDivider"); foreach (var category in lootContainers) { var setting = lootContainers[category.Key] as Dictionary<string, object>; textTable.AddRow(new string[] { category.Key.ToString(), Convert.ToString(setting["Items"]), (Convert.ToBoolean(setting["Enabled"]) ? "Yes" : "No"), (Convert.ToBoolean(setting["UseVanilla"]) ? "Yes" : "No"), Convert.ToString(setting["UsedMultiplier"]), Convert.ToString(setting["MinAmountDivider"]), }); } SendReply(arg, "\n" + textTable.ToString()); }  [ConsoleCommand("al.containeradd")] void consoleContainerAdd(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; if (arg.Args == null || arg.Args.Length > 1) { var sb = new StringBuilder(); var n = 0; foreach (var container in AllContainerTypes) { if (!lootContainers.ContainsKey(container.Key)) { if (n > 0) sb.Append(", "); sb.Append(container.Key); n++; } } var sb2 = new StringBuilder(); sb2.AppendLine("\n> Available containertypes:"); sb2.AppendLine(sb.ToString()); sb2.AppendLine("> Names with whitespace need to be typed within quotes \"...\". Choose only one per command"); SendReply(arg, sb2.ToString()); return; } if (arg.Args != null && arg.Args.Length == 1) { if (lootContainers.ContainsKey(arg.Args[0])) { SendReply(arg, $"Container '{arg.Args[0]}' already included"); return; } if (!AllContainerTypes.ContainsKey(arg.Args[0])) { SendReply(arg, $"Container '{arg.Args[0]}' does not exist"); return; } var loot = GameManager.server.CreateEntity(AllContainerTypes[arg.Args[0]], new Vector3(), new Quaternion(), false).GetComponent<LootContainer>(); var container = new Dictionary<string, object>(); var addslot = 0;  if (loot.maxDefinitionsToSpawn == 1) addslot++; container.Add("Items", loot.maxDefinitionsToSpawn + addslot); if (itemSlotVariance) container.Add("ItemsVariance", -1); container.Add("Enabled", true); container.Add("UseVanilla", false); container.Add("UsedMultiplier", 1); container.Add("MinAmountDivider", 1); container.Add("ScrapAmount", loot.scrapAmount); GetLootSpawn(AllLootSpawns[arg.Args[0]], arg.Args[0]); if ((lootData[arg.Args[0]] as Dictionary<string, object>) != null && (lootData[arg.Args[0]] as Dictionary<string, object>).Count() < (loot.maxDefinitionsToSpawn + 1)) { container["Items"] = (lootData[arg.Args[0]] as Dictionary<string, object>).Count(); } lootContainers.Add(loot.ShortPrefabName, container); try { loot.KillMessage(); } catch { } lootTable = getFile("LootTables"); lootTable.Set("LootContainer", lootContainers); lootTable.Set("LootData", lootData); lootTable.Save(); lootTable.Clear(); SendReply(arg, $"Container '{arg.Args[0]}' was added. 'al.reload' required"); } }  [ConsoleCommand("al.containerremove")] void consoleContainerRemove(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; if (arg.Args == null || arg.Args.Length > 1) { SendReply(arg, "You need to type one included containertype. Check those by 'al.containertypes'"); return; } if (arg.Args != null && arg.Args.Length == 1) { if (!lootContainers.ContainsKey(arg.Args[0])) { SendReply(arg, $"Container '{arg.Args[0]}' not included"); return; } lootContainers.Remove(arg.Args[0]); lootTable = getFile("LootTables"); lootTable.Set("LootContainer", lootContainers); lootData.Remove(arg.Args[0]); lootTable.Set("LootData", lootData); lootTable.Save(); lootTable.Clear(); SendReply(arg, $"Container '{arg.Args[0]}' was removed. 'al.reload' required"); } }  [ConsoleCommand("al.containerset")] void consoleContainerSet(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; if (arg.Args == null || arg.Args.Length < 5) { SendReply(arg, "You need to type one included containertype. Check those by 'al.containertypes'"); SendReply(arg, "Example: al.containerset <name> <true|false(Enabled)> <x(Items)> <true|false(Vanilla)> <x(Multiplier)> <x(AmountDivider)>"); return; } if (arg.Args != null && arg.Args.Length > 1) { if (!lootContainers.ContainsKey(arg.Args[0])) { SendReply(arg, $"Container '{arg.Args[0]}' not included"); return; } bool enable = false; if (!bool.TryParse(arg.Args[1], out enable)) { SendReply(arg, $"Set 'true(enable)' or 'false(disable)'"); return; } int items = -1; if (arg.Args.Length > 2) if (!int.TryParse(arg.Args[2], out items)) { SendReply(arg, $"Set a full number for Items"); return; } bool vanilla = false; if (arg.Args.Length > 3) if (!bool.TryParse(arg.Args[3], out vanilla)) { SendReply(arg, $"Set 'true(enable)' or 'false(disable)' for UseVanilla"); return; } int multiplier = -1; if (arg.Args.Length > 4) if (!int.TryParse(arg.Args[4], out multiplier)) { SendReply(arg, $"Set a full number for Multiplier"); return; } int divider = -1; if (arg.Args.Length > 5) if (!int.TryParse(arg.Args[5], out divider)) { SendReply(arg, $"Set a full number for AmountDivider"); return; } var container = lootContainers[arg.Args[0]] as Dictionary<string, object>; container["Enabled"] = enable; if (items > 0) container["Items"] = items; if (multiplier > 0) container["UsedMultiplier"] = multiplier; container["UseVanilla"] = vanilla; if (divider > 0) container["MinAmountDivider"] = divider; lootContainers[arg.Args[0]] = container; SendReply(arg, $"\nNew Setting for '{arg.Args[0]}' | Enabled: {(bool)container["Enabled"]} | Items: {(int)container["Items"]} | Vanilla: {(bool)container["UseVanilla"]} |  Multiplier: {(int)container["UsedMultiplier"]} | MinAmountDivider: {(int)container["MinAmountDivider"]}"); lootTable = getFile("LootTables"); lootTable.Set("LootContainer", lootContainers); lootTable.Save(); lootTable.Clear(); SendReply(arg, $"Container '{arg.Args[0]}' was modified. Plugin reload required for instant effect on item counts"); SendReply(arg, $"Changes to Vanilla usage need 'al.lootreload reset' to take effect on the tables"); } }  [ConsoleCommand("al.categoryset")] void consoleCategorySet(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; if (arg.Args == null || arg.Args.Length < 3) { SendReply(arg, "You need to type one included category. Check those by 'al.categorylist'"); SendReply(arg, "Example: al.categoryset <name> <x(VanillaMultiplier)> <true|false(DropSkinned)> "); return; } if (arg.Args != null && arg.Args.Length > 1) { if (!lootCategoryLimits.ContainsKey(arg.Args[0])) { SendReply(arg, $"Category '{arg.Args[0]}' not included"); return; } int multi = -1; if (arg.Args.Length > 1) if (!int.TryParse(arg.Args[1], out multi)) { SendReply(arg, $"Set a full number for minLimit"); return; } bool skinned = false; if (arg.Args.Length > 2) if (!bool.TryParse(arg.Args[2], out skinned)) { SendReply(arg, $"Set 'true(enable)' or 'false(disable)'"); return; } var category = lootCategoryLimits[arg.Args[0]] as Dictionary<string, object>; category["DropSkinned"] = skinned; if (multi < 1) multi = 1; category["VanillaMultiplier"] = multi; lootCategoryLimits[arg.Args[0]] = category; SendReply(arg, $"New Setting for '{arg.Args[0]}' | DropSkinned: {(bool)category["DropSkinned"]} | VanillaMultiplier: {(int)category["VanillaMultiplier"]}"); Config["LootCategorys", "Limits"] = lootCategoryLimits; Config.Save(); SendReply(arg, $"Category '{arg.Args[0]}' was modified. Plugin reload required for instant effect on DropSkinned"); SendReply(arg, $"Changes to Vanilla usage need 'al.lootreload reset' to take effect  on the tables"); } }  [ConsoleCommand("al.showcontainers")] void consoleShowContainers(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; var LootContainers = Resources.FindObjectsOfTypeAll<LootContainer>().Where(c => c.isActiveAndEnabled).Cast<BaseEntity>().ToList(); Dictionary<string, int> LootCounter = new Dictionary<string, int>(); foreach (var container in LootContainers) { if (!LootCounter.ContainsKey(container.ShortPrefabName)) LootCounter.Add(container.ShortPrefabName, 0); LootCounter[container.ShortPrefabName] += 1; } TextTable textTable = new TextTable(); textTable.AddColumn("Type"); textTable.AddColumn("Count"); textTable.AddColumn("Enabled"); foreach (var counter in LootCounter) { string active; object check; if (lootContainers.TryGetValue(counter.Key, out check)) { active = (check as Dictionary<string, object>)["Enabled"].ToString(); } else active = "n.a."; textTable.AddRow(new string[] { counter.Key.ToString(), counter.Value.ToString(), active }); } SendReply(arg, "\n" + textTable.ToString()); }  [ConsoleCommand("al.cmds")] void consoleComandsList(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; var sb = new StringBuilder(); sb.AppendLine("\n==== Command List ================\n"); sb.AppendLine($"al.reload".PadRight(20) + "| Reloads the whole plugin internally"); sb.AppendLine($"al.refreshboxes".PadRight(20) + "| Refreshes the complete server loot"); sb.AppendLine($"al.rarityreload".PadRight(20) + "| Reloads the item raritys into server after changing them"); sb.AppendLine($"al.rarityset".PadRight(20) + "| Sets the item rarity for a specific item"); sb.AppendLine($"al.lootreload".PadRight(20) + "| Can with \"reset\" be used to prefill all item settings with new defaults"); sb.AppendLine($"al.enable".PadRight(20) + "| Enables the plugin from passive state"); sb.AppendLine($"al.disable".PadRight(20) + "| Disables the plugin into passive state"); sb.AppendLine($"al.itemlimit".PadRight(20) + "| Sets the maximum item limit for a given item"); sb.AppendLine($"al.itemremove".PadRight(20) + "| Removes an item complete from the loot tables"); sb.AppendLine($"al.itemfind".PadRight(20) + "| Shows the entries for a specific item"); sb.AppendLine($"al.itemadd".PadRight(20) + "| Adds an item with a given limit to the specific containers"); sb.AppendLine($"al.categorylist".PadRight(20) + "| Lists the current category defaults"); sb.AppendLine($"al.categoryset".PadRight(20) + "| Modifies a given category in the plugin config"); sb.AppendLine($"al.containertypes".PadRight(20) + "| Lists the added container types and their status"); sb.AppendLine($"al.containeradd".PadRight(20) + "| Adds a not included containtertype to your loot tables"); sb.AppendLine($"al.containerremove".PadRight(20) + "| Removes a specific containtertype from your loot tables"); sb.AppendLine($"al.containerset".PadRight(20) + "| Modifies a specific containtertype in your loot tables"); sb.AppendLine($"al.showcontainers".PadRight(20) + "| Lists all current containers on map"); sb.AppendLine($"al.showconfig".PadRight(20) + "| Shows and explains the current config options"); sb.AppendLine($"al.searchitems".PadRight(20) + "| Search any game item(s) by partial name"); SendReply(arg, sb.ToString()); }  [ConsoleCommand("al.showconfig")] void consoleShowConfig(ConsoleSystem.Arg arg) { if (arg.Connection != null && arg.Connection.authLevel < setupAuthLevel) return; var sb = new StringBuilder(); sb.AppendLine("\n==== Current config options ================\n"); sb.AppendLine($"pluginEnabled".PadRight(25) + "| Enables/disables the plugin loot spawning > " + pluginEnabled); sb.AppendLine($"refreshMinutes".PadRight(25) + "| Time in minutes after a \"looted-not-empty\" container will be refreshed > " + refreshMinutes); sb.AppendLine($"debugLootRepopulation".PadRight(25) + "| This would log the container refreshs to console > " + debugLootRepopulation); sb.AppendLine($"adminInputLootRefresh".PadRight(25) + "| Enables constant loot/inventory refresh on loot \"hit with a hammer\" by an admin > " + adminInputLootRefresh); sb.AppendLine($"adminLootRefreshInterval".PadRight(25) + "| The interval in seconds for the admin loot check > " + (float)adminLootRefreshInterval); sb.AppendLine($"setupAuthLevel".PadRight(25) + "| AuthLevel to have access to the plugin commands > " + setupAuthLevel); sb.AppendLine($"includeWorkShopSkins".PadRight(25) + "| Randomize also WorkShopskins (client lagging possible) > " + includeWorkShopSkins); sb.AppendLine($"blockPlayerItemInput".PadRight(25) + "| Blocks input of player items back into lootcontainers > " + blockPlayerItemInput); sb.AppendLine($"lootStackFixEnable".PadRight(25) + "| Removal of stacked loot container at same position > " + lootStackFixEnable); sb.AppendLine($"lootStackFixRange".PadRight(25) + "| Range to check for stacked loot containers > " + lootStackFixRange); sb.AppendLine($"itemSlotVariance".PadRight(25) + "| Provides container item slots randomization > " + itemSlotVariance); sb.AppendLine($"enableHeliLoadOut".PadRight(25) + "| Provides predefined loadouts for heli crates > " + enableHeliLoadOut); sb.AppendLine($"enableFancyDropLoot".PadRight(25) + "| Provides seperate itemlists for all drop types > " + enableFancyDropLoot); sb.AppendLine($"useSkinBoxSkins".PadRight(25) + "| Can re-use the skins loaded by Skinbox > " + useSkinBoxSkins); SendReply(arg, sb.ToString()); }  bool isSupplyDropActive() { if (!pluginEnabled) return false; object drop; if (lootContainers.TryGetValue("supply_drop", out drop)) { if ((bool)(drop as Dictionary<string, object>)["Enabled"]) return true; } return false; }  void OnHammerHit(BasePlayer player, HitInfo info) { if (!initialized || !pluginEnabled || !adminInputLootRefresh || info == null || info.HitEntity == null || info.HitEntity.GetComponent<LootContainer>() == null || player.net.connection.authLevel < setupAuthLevel) return; if ((enableHeliLoadOut && info.HitEntity.ShortPrefabName == "heli_crate") || (enableFancyDropLoot && info.HitEntity.ShortPrefabName == "supply_drop")) { player.ChatMessage($"Admin lootcheck deactivated on '{info.HitEntity.ShortPrefabName}'"); return; } if (showAdminLootInfo) player.ChatMessage($"Starting admin lootcheck of type '{info.HitEntity.ShortPrefabName}'"); var loot = info.HitEntity.GetComponent<StorageContainer>(); loot.gameObject.AddComponent<AdminLootHandler>(); player.inventory.loot.StartLootingEntity(loot, false); player.inventory.loot.AddContainer(loot.inventory); player.inventory.loot.SendImmediate(); player.ClientRPCPlayer(null, player, "RPC_OpenLootPanel", loot.panelName, null, null, null, null); }  class AdminLootHandler : FacepunchBehaviour { void Awake() { if (!al.initialized || !al.pluginEnabled) return; InvokeRepeating(Repeater, al.adminLootRefreshInterval, al.adminLootRefreshInterval); }  void Repeater() { if (!al.initialized || !al.pluginEnabled) return;  if (al.lootContainers.ContainsKey(GetComponent<BaseEntity>().ShortPrefabName) && (bool)(al.lootContainers[GetComponent<BaseEntity>().ShortPrefabName] as Dictionary<string, object>)["Enabled"]) al.PopulateContainer(GetComponent<LootContainer>()); else GetComponent<LootContainer>().SpawnLoot(); }  private void PlayerStoppedLooting(BasePlayer player) { CancelInvoke(Repeater); Destroy(this); } }  class RefreshHandler : FacepunchBehaviour { void Spawner() { if (!al.initialized || !al.pluginEnabled) { Destroy(this); return; } if (al.debugLootRepopulation) al.Puts($"DBG: {GetComponent<BaseEntity>().ShortPrefabName}({GetComponent<BaseEntity>().transform.position}) | Timer done, refill!"); al.PopulateContainer(GetComponent<LootContainer>()); }  public void Reset() { CancelInvoke(Spawner); }  void PlayerStoppedLooting(BasePlayer player) { CancelInvoke(Spawner); if (GetComponent<StorageContainer>() == null || GetComponent<StorageContainer>().inventory == null || !al.initialized || !al.pluginEnabled) { Destroy(this); return; } var timer = UnityEngine.Random.Range(Convert.ToSingle(al.refreshMinutes) * 60 * 0.85f, Convert.ToSingle(al.refreshMinutes) * 60 * 1.15f); Invoke(Spawner, timer); if (al.debugLootRepopulation) al.Puts($"DBG: {GetComponent<BaseEntity>().ShortPrefabName}({GetComponent<BaseEntity>().transform.position}) | Timer to refill: {timer}"); }  void OnDestroy() { CancelInvoke(Spawner); Destroy(this); } } } }